"""PinStore for managing pinned certificate fingerprints per host."""

import json
import os


class PinStore:
    """Stores pinned certificate fingerprints for hosts.

    The pins are stored as a mapping of host -> list of SHA-256 fingerprints.
    """

    def __init__(self, pins: dict):
        self._pins = pins

    @classmethod
    def load(cls) -> "PinStore":
        """Load the PinStore from the default pinned certificates file."""
        # Default embedded pins for vendor feed hosts
        default_pins = {
            "feeds.tessaro.net": [
                "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9"
            ]
        }
        return cls(default_pins)

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        """Check if the given fingerprint matches any pinned fingerprint for the host.

        Args:
            host: The hostname to check.
            cert_fingerprint: SHA-256 fingerprint of the certificate.

        Returns:
            True if the fingerprint matches a pinned value for the host.
        """
        if host not in self._pins:
            return False
        return cert_fingerprint in self._pins[host]
